const body = $json.body ?? $json;
const requestId = body.request_id ?? 'missing-request-id';
const rawText = String(body.raw_text ?? 'I want a mermaid coloring page');
const query = rawText.toLowerCase().includes('mermaid') ? 'mermaid coloring page' : `${rawText} coloring page`;
const svg = (title, accent) => {
  const content = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1200"><rect width="900" height="1200" fill="#fffaf0"/><rect x="45" y="45" width="810" height="1110" rx="42" fill="none" stroke="${accent}" stroke-width="18"/><circle cx="450" cy="330" r="120" fill="none" stroke="#2d3142" stroke-width="18"/><path d="M315 580c80-120 190-120 270 0 35 52 34 132-3 206l-132 260-132-260c-37-74-38-154-3-206z" fill="none" stroke="#2d3142" stroke-width="18"/><path d="M285 295c80-65 250-65 330 0M360 335c25 24 55 24 80 0M460 335c25 24 55 24 80 0" fill="none" stroke="#2d3142" stroke-width="14" stroke-linecap="round"/><text x="450" y="1110" text-anchor="middle" font-family="Arial, sans-serif" font-size="48" fill="#2d3142">${title}</text></svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(content)}`;
};
return [{
  json: {
    request_id: requestId,
    query,
    images: [
      {
        id: 'img_01',
        title: 'Mermaid coloring page',
        source: 'n8n-mock',
        thumbnail_url: svg('Mermaid', '#287c76'),
        full_url: svg('Mermaid', '#287c76'),
        print_url: 'https://example.com/mermaid1-print.jpg',
        content_type: 'image/jpeg',
        width: 1200,
        height: 1600,
        printable: true
      },
      {
        id: 'img_02',
        title: 'Cute mermaid outline',
        source: 'n8n-mock',
        thumbnail_url: svg('Cute Mermaid', '#8a5a44'),
        full_url: svg('Cute Mermaid', '#8a5a44'),
        print_url: 'https://example.com/mermaid2-print.jpg',
        content_type: 'image/jpeg',
        width: 1024,
        height: 1536,
        printable: true
      }
    ]
  }
}];
